<?php
require_once __DIR__ . '/../config/database.php';require_once __DIR__ . '/../helpers/auth.php';require_login();require_once __DIR__ . '/../helpers/escape.php';require_once __DIR__ . '/../helpers/csrf.php';
$pageTitle='Supplier';$message='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(($_POST['action']??'')==='add'){ $name=trim($_POST['name']??'');$contact=trim($_POST['contact']??'');$phone=trim($_POST['phone']??'');if($name==='')$error='Nama supplier wajib diisi.';else{$st=$pdo->prepare('INSERT INTO suppliers(name,contact_person,phone) VALUES(?,?,?)');$st->execute([$name,$contact,$phone]);$message='Supplier ditambahkan.';}}elseif(($_POST['action']??'')==='link'){require_admin();$pid=(int)$_POST['product_id'];$sid=(int)$_POST['supplier_id'];$price=filter_var($_POST['supplier_price']??0,FILTER_VALIDATE_FLOAT);if($pid<1||$sid<1||$price===false||$price<0)$error='Data hubungan supplier tidak valid.';else{try{$st=$pdo->prepare('INSERT INTO product_suppliers(product_id,supplier_id,supplier_price) VALUES(?,?,?) ON DUPLICATE KEY UPDATE supplier_price=VALUES(supplier_price)');$st->execute([$pid,$sid,$price]);$message='Hubungan produk dan supplier disimpan.';}catch(PDOException $e){$error='Gagal menyimpan hubungan.';}}}}
$suppliers=$pdo->query('SELECT * FROM suppliers ORDER BY name')->fetchAll();$products=$pdo->query('SELECT id,name,sku FROM products ORDER BY name')->fetchAll();$links=$pdo->query('SELECT ps.supplier_price,p.name product_name,p.sku,s.name supplier_name FROM product_suppliers ps JOIN products p ON p.id=ps.product_id JOIN suppliers s ON s.id=ps.supplier_id ORDER BY p.name,s.name')->fetchAll();require '_header.php';
?>
<h1>Data Supplier</h1><?php if($message):?><div class="notice"><?=e($message)?></div><?php endif;?><?php if($error):?><div class="error"><?=e($error)?></div><?php endif;?>
<div class="card"><h2>Tambah Supplier</h2><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="add"><label>Nama supplier</label><input name="name" required><label>Nama kontak</label><input name="contact"><label>Nomor telepon</label><input name="phone"><div class="actions"><button>Tambah supplier</button></div></form></div>
<?php if(($_SESSION['user']['role']??'')==='admin' && $products && $suppliers):?><div class="card"><h2>Hubungkan Produk dengan Supplier</h2><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="link"><label>Produk</label><select name="product_id"><?php foreach($products as $p):?><option value="<?=e($p['id'])?>"><?=e($p['sku'].' - '.$p['name'])?></option><?php endforeach;?></select><label>Supplier</label><select name="supplier_id"><?php foreach($suppliers as $s):?><option value="<?=e($s['id'])?>"><?=e($s['name'])?></option><?php endforeach;?></select><label>Harga supplier (Rp)</label><input type="number" name="supplier_price" min="0" step=".01" value="0"><div class="actions"><button>Simpan hubungan</button></div></form></div><?php endif;?>
<div class="card"><h2>Daftar Supplier</h2><div class="table-wrap"><table><tr><th>Nama</th><th>Kontak</th><th>Telepon</th></tr><?php foreach($suppliers as $s):?><tr><td><?=e($s['name'])?></td><td><?=e($s['contact_person'])?></td><td><?=e($s['phone'])?></td></tr><?php endforeach;?></table></div></div>
<div class="card"><h2>Relasi Produk - Supplier</h2><div class="table-wrap"><table><tr><th>SKU</th><th>Produk</th><th>Supplier</th><th>Harga supplier</th></tr><?php foreach($links as $l):?><tr><td><?=e($l['sku'])?></td><td><?=e($l['product_name'])?></td><td><?=e($l['supplier_name'])?></td><td>Rp <?=number_format($l['supplier_price'],0,',','.')?></td></tr><?php endforeach;?></table></div></div>
<?php require '_footer.php';?>
